#include <stdio.h>
#include <stdint.h>

typedef uint32_t ext4_lblk_t;

int check_valid(ext4_lblk_t lblock, int len) {
    if (len == 0) return 0;
    if (lblock + len <= lblock) return 0;
    return 1;
}

void check_bug(ext4_lblk_t lblk, int len) {
    ext4_lblk_t end = lblk + len - 1;
    if (end < lblk) {
        printf("BUG triggered for lblk=%u len=%d\n", lblk, len);
    } else {
        printf("No BUG for lblk=%u len=%d\n", lblk, len);
    }
}

int main() {
    ext4_lblk_t lblks[] = {0xFFFFFFFF, 0xFFFFFFFE, 0x7FFFFFFF, 100};
    int lengths[] = {0, 1, 2, 32768};

    for (int i=0; i<4; i++) {
        for (int j=0; j<4; j++) {
            ext4_lblk_t l = lblks[i];
            int len = lengths[j];
            printf("Checking lblk=%u, len=%d: ", l, len);
            int valid = check_valid(l, len);
            if (valid) {
                 printf("VALID. ");
                 check_bug(l, len);
            } else {
                 printf("INVALID.\n");
            }
        }
    }
    return 0;
}

int len = ext4_ext_get_actual_len(ex);

if (lblk + len <= lblk)
	break;

if (prev && (prev != lblk)) {
	if (prev > lblk)
		break;
	ext4_es_cache_extent(inode, prev, lblk - prev, ~0,
			     EXTENT_STATUS_HOLE);
}

